//! CLI contract tests for the compliance audits — exit codes + JSON schema
//! freeze (E-2-03, spec: `research/tallow-v1/cycle-02/08-compliance-design.md` §b).
//!
//! These run the real compiled binary (`CARGO_BIN_EXE_tallow`). The exit-code
//! contract is the frozen §b table; the JSON key sets are pinned by the goldens
//! under `tests/fixtures/audit_golden/` (generated by the E-2-03 wave; the
//! generation script lives in `research/tallow-v1/exec/E-2-03-audit-exit-codes.md`).
//! A failure here means either a real regression or an unannounced schema/exit
//! change — regenerate goldens only for an intentional, spec'd change.
//!
//! Runnable with: `cargo test --test audit_cli_contract --offline`

use std::path::PathBuf;
use std::process::{Command, Output};

const VALID: &str = "tests/fixtures/legal_valid.tl";
const INVALID: &str = "tests/fixtures/legal_invalid.tl";

const DISCLAIMER: &str =
    "This output is compliance tooling — not legal advice and not a certification.";

/// (variant name, flags) for the five frozen audit variants.
const VARIANTS: [(&str, &[&str]); 5] = [
    ("default", &[]),
    ("cra", &["--cra"]),
    ("nis2", &["--nis2"]),
    ("dora", &["--dora"]),
    ("ai_act", &["--ai-act"]),
];

fn tallow(args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_tallow"))
        .current_dir(env!("CARGO_MANIFEST_DIR"))
        .env_remove("TALLOW_ADVISORY_FILE")
        .args(args)
        .output()
        .expect("spawn tallow")
}

fn exit_of(out: &Output) -> i32 {
    out.status.code().expect("tallow terminated by signal")
}

/// Run `tallow audit <flags> <file> [--format json]`. Returns (exit code, parsed
/// JSON when `json` is true — invalid JSON panics with the stderr tail).
fn run_audit(flags: &[&str], file: &str, json: bool) -> (i32, Option<serde_json::Value>) {
    let mut args = vec!["audit"];
    args.extend_from_slice(flags);
    args.push(file);
    if json {
        args.push("--format");
        args.push("json");
    }
    let out = tallow(&args);
    let value = json.then(|| {
        serde_json::from_slice(&out.stdout).unwrap_or_else(|e| {
            panic!(
                "audit {flags:?} {file} --format json: invalid JSON ({e}); stderr: {}",
                String::from_utf8_lossy(&out.stderr)
            )
        })
    });
    (exit_of(&out), value)
}

/// Version-bearing and time-bearing values are provenance stamps, not schema. They
/// change on every release by design, so pinning them in a golden whose job is to
/// catch *unintended* drift guarantees a false alarm at every version bump — and a
/// false alarm teaches the reader to regenerate without looking, which is how a
/// tripwire quietly stops working. The version and the content-hash tail are
/// normalised exactly as timestamps already were.
fn normalize(v: &mut serde_json::Value) {
    let pkg_version = env!("CARGO_PKG_VERSION");
    let tool_creator = format!("Tool: tallow-{pkg_version}");
    match v {
        serde_json::Value::Object(map) => {
            for (k, val) in map.iter_mut() {
                if k == "tallow_version" {
                    *val = serde_json::json!("<ver>");
                } else {
                    normalize(val);
                }
            }
        }
        serde_json::Value::Array(items) => items.iter_mut().for_each(normalize),
        serde_json::Value::String(s) if is_rfc3339(s) => *s = "<ts>".to_string(),
        // CycloneDX metadata.tools[].version carries the bare version string.
        serde_json::Value::String(s) if s.as_str() == pkg_version => *s = "<ver>".to_string(),
        // SPDX creationInfo.creators carries "Tool: tallow-<version>".
        serde_json::Value::String(s) if s.as_str() == tool_creator.as_str() => {
            *s = "Tool: tallow-<ver>".to_string()
        }
        // SPDX documentNamespace ends in a content hash, so it moves whenever any
        // other field does. The identity is asserted separately
        // (`spdx_namespace_names_the_project_host`); the variable tail is stamped.
        serde_json::Value::String(s) if is_spdx_namespace(s) => *s = stamp_spdx_namespace(s),
        _ => {}
    }
}

fn is_spdx_namespace(s: &str) -> bool {
    s.starts_with("https://") && s.contains("/spdx/")
}

/// `<scheme>://<host>/…/spdx/<name>/<version>/<hash>` → everything up to the name is
/// kept verbatim, then the version and hash become placeholders.
fn stamp_spdx_namespace(s: &str) -> String {
    if let Some((head, _hash)) = s.rsplit_once('/') {
        if let Some((head2, _ver)) = head.rsplit_once('/') {
            return format!("{head2}/<ver>/<hash>");
        }
    }
    s.to_string()
}

fn is_rfc3339(s: &str) -> bool {
    s.len() == 20
        && s.as_bytes()[4] == b'-'
        && s.as_bytes()[7] == b'-'
        && s.as_bytes()[10] == b'T'
        && s.ends_with('Z')
}

// ── Exit-code freeze table (cycle-02/08 §b) ─────────────────────────────────

#[test]
fn default_audit_exit_codes_are_frozen() {
    assert_eq!(run_audit(&[], VALID, false).0, 0, "compliant text");
    assert_eq!(run_audit(&[], VALID, true).0, 0, "compliant json");
    assert_eq!(run_audit(&[], INVALID, false).0, 2, "violation text ⇒ LEGAL_VIOLATION");
    let (code, v) = run_audit(&[], INVALID, true);
    assert_eq!(code, 2, "violation json path must exit non-zero (was 0 — E-2-03 fix)");
    assert_eq!(v.unwrap()["compliance_status"], "NON-COMPLIANT");
}

#[test]
fn cra_audit_exit_codes_are_frozen() {
    assert_eq!(run_audit(&["--cra"], VALID, false).0, 0);
    assert_eq!(run_audit(&["--cra"], VALID, true).0, 0);
    assert_eq!(run_audit(&["--cra"], INVALID, false).0, 2, "errors > 0 ⇒ 2");
    let (code, v) = run_audit(&["--cra"], INVALID, true);
    assert_eq!(code, 2, "JSON path must exit non-zero on violations (was 0)");
    assert!(v.unwrap()["cra_report"]["errors"].as_u64().unwrap() > 0);
    // --strict escalates any Annex-I check that is not `pass` (fixture project
    // has no lockfile ⇒ "Update capability" fails).
    assert_eq!(run_audit(&["--cra", "--strict"], VALID, false).0, 2, "--strict text");
    assert_eq!(run_audit(&["--cra", "--strict"], VALID, true).0, 2, "--strict json");
}

#[test]
fn nis2_audit_exit_codes_are_frozen() {
    assert_eq!(run_audit(&["--nis2"], VALID, false).0, 0);
    assert_eq!(run_audit(&["--nis2"], VALID, true).0, 0);
    // legal_invalid has no crypto usage: the frozen FAIL definition
    // (nis2_errors + forbidden_count) is clean for it — exit stays 0.
    assert_eq!(run_audit(&["--nis2"], INVALID, false).0, 0);
    assert_eq!(run_audit(&["--nis2"], INVALID, true).0, 0);
    // Forbidden algorithm (MD5) ⇒ nis2_errors > 0 ⇒ 2, both formats.
    assert_eq!(run_audit(&["--nis2"], "tests/fixtures/nis2_fail.tl", false).0, 2);
    let (code, v) = run_audit(&["--nis2"], "tests/fixtures/nis2_fail.tl", true);
    assert_eq!(code, 2, "JSON path must exit non-zero on forbidden crypto (was 0)");
    assert!(v.unwrap()["nis2_report"]["errors"].as_u64().unwrap() > 0);
    // --strict escalates failing Art.21 measures.
    assert_eq!(run_audit(&["--nis2", "--strict"], VALID, false).0, 2, "--strict text");
    assert_eq!(run_audit(&["--nis2", "--strict"], VALID, true).0, 2, "--strict json");
}

#[test]
fn dora_audit_exit_codes_are_frozen() {
    // legal_valid: Art.19 FAIL (no DoraCitIncident) ⇒ checks_pass < total ⇒ 2.
    assert_eq!(run_audit(&["--dora"], VALID, false).0, 2, "FAIL text ⇒ 2 (new)");
    let (code, v) = run_audit(&["--dora"], VALID, true);
    assert_eq!(code, 2, "FAIL json ⇒ 2 (new)");
    assert_eq!(
        v.unwrap()["dora_report"]["compliance_summary"]["status"],
        "PARTIAL"
    );
    // All checks pass ⇒ 0; DORA `--strict` adds no further classes.
    assert_eq!(run_audit(&["--dora"], "tests/fixtures/dora_pass.tl", false).0, 0);
    assert_eq!(run_audit(&["--dora"], "tests/fixtures/dora_pass.tl", true).0, 0);
    assert_eq!(run_audit(&["--dora", "--strict"], "tests/fixtures/dora_pass.tl", true).0, 0);
    assert_eq!(run_audit(&["--dora", "--strict"], VALID, true).0, 2);
}

#[test]
fn ai_act_audit_exit_codes_are_frozen() {
    // prohibited > 0 ⇒ 2, both formats.
    assert_eq!(
        run_audit(&["--ai-act"], "tests/fixtures/ai_act_prohibited.tl", false).0,
        2
    );
    let (code, v) = run_audit(&["--ai-act"], "tests/fixtures/ai_act_prohibited.tl", true);
    assert_eq!(code, 2, "prohibited json ⇒ 2 (new)");
    assert!(
        v.unwrap()["ai_act_report"]["ai_system_inventory"]["prohibited"]
            .as_u64()
            .unwrap()
            > 0
    );
    // All five checks pass ⇒ 0; COMPLIANT survives --strict.
    assert_eq!(run_audit(&["--ai-act"], "tests/fixtures/ai_act_pass.tl", false).0, 0);
    assert_eq!(run_audit(&["--ai-act"], "tests/fixtures/ai_act_pass.tl", true).0, 0);
    assert_eq!(run_audit(&["--ai-act", "--strict"], "tests/fixtures/ai_act_pass.tl", true).0, 0);
    // Frozen FAIL definition: Art.9/Art.12 FAIL ⇒ 2 even without --strict.
    // legal_valid has no AiInferenceLog ⇒ art12 FAIL (spec note in E-2-03 log:
    // §b's test-list row claiming 0 here contradicts the freeze table).
    let (code, v) = run_audit(&["--ai-act"], VALID, true);
    assert_eq!(code, 2, "art12 FAIL ⇒ 2");
    assert_eq!(
        v.unwrap()["ai_act_report"]["art12_record_keeping"]["status"],
        "FAIL"
    );
    // PARTIAL without Art.9/Art.12 FAIL ⇒ 0 by default; --strict escalates.
    assert_eq!(
        run_audit(&["--ai-act"], "tests/fixtures/ai_act_partial_strict.tl", false).0,
        0
    );
    assert_eq!(
        run_audit(&["--ai-act", "--strict"], "tests/fixtures/ai_act_partial_strict.tl", false).0,
        2,
        "--strict escalates PARTIAL (text)"
    );
    assert_eq!(
        run_audit(&["--ai-act", "--strict"], "tests/fixtures/ai_act_partial_strict.tl", true).0,
        2,
        "--strict escalates PARTIAL (json)"
    );
}

// ── JSON schema freeze (golden key sets + additive frozen keys) ─────────────

#[test]
fn json_carries_frozen_schema_and_disclaimer_keys() {
    for (name, flags) in VARIANTS {
        let (_c, v) = run_audit(flags, VALID, true);
        let v = v.expect("json output");
        assert_eq!(v["schema"], format!("tallow.audit.{name}.v1"), "{name}: schema key");
        assert_eq!(v["disclaimer"], DISCLAIMER, "{name}: disclaimer key");
        // The default report's version field no longer reports the stale 0.2.0
        // literal (E-2-03 fix).
        if name == "default" {
            assert_eq!(v["tallow_version"], env!("CARGO_PKG_VERSION"), "default: version");
        }
    }
}

#[test]
fn json_matches_checked_in_goldens() {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/audit_golden");
    // Regeneration is a documented command, not a manual JSON edit — the same shape
    // as the room-id vector harness. Normalised output is what gets stored, so the
    // fixture holds placeholders and never drifts with the version again.
    let regenerate = std::env::var("REGENERATE_AUDIT_GOLDENS").is_ok();
    for (name, flags) in VARIANTS {
        let (_c, v) = run_audit(flags, VALID, true);
        let mut actual = v.expect("json output");
        normalize(&mut actual);
        let path = dir.join(format!("{name}.json"));
        if regenerate {
            let rendered = format!("{}\n", serde_json::to_string_pretty(&actual).unwrap());
            std::fs::write(&path, rendered)
                .unwrap_or_else(|e| panic!("write golden {}: {e}", path.display()));
            continue;
        }
        let golden: serde_json::Value = serde_json::from_str(
            &std::fs::read_to_string(&path)
                .unwrap_or_else(|e| panic!("read golden {}: {e}", path.display())),
        )
        .expect("golden parses");
        assert_eq!(
            serde_json::to_string_pretty(&actual).unwrap(),
            serde_json::to_string_pretty(&golden).unwrap(),
            "schema drift for audit variant `{name}` vs {} — regenerate with \
             REGENERATE_AUDIT_GOLDENS=1 only for an intentional, spec'd schema change \
             (cycle-02/08 §b)",
            path.display()
        );
    }
}

/// Templating the namespace's hash must not erase the check on whose host it names.
/// This is what keeps the project's own domain pinned after `normalize` stamps the
/// variable tail: shape asserted live, bytes compared only up to the stamp.
///
/// Not every variant emits an SPDX block — the bare default report does not — so absent
/// blocks are skipped. The trailing count guard exists so that a future change which
/// stops emitting SPDX everywhere fails here instead of turning this test vacuous.
#[test]
fn spdx_namespace_names_the_project_host() {
    let mut seen = 0;
    for (name, flags) in VARIANTS {
        let (_c, v) = run_audit(flags, VALID, true);
        let v = v.expect("json output");
        let Some(ns) = v
            .get("spdx")
            .and_then(|s| s.get("documentNamespace"))
            .and_then(|n| n.as_str())
        else {
            continue;
        };
        seen += 1;
        assert!(
            ns.starts_with("https://github.com/aamirmanisa/tallowsphere/spdx/"),
            "{name}: documentNamespace must name the project's own host and path, got `{ns}`"
        );
        assert!(
            stamp_spdx_namespace(ns).ends_with("/<ver>/<hash>"),
            "{name}: namespace must end in a name/version/hash triple, got `{ns}`"
        );
    }
    assert!(
        seen > 0,
        "no audit variant emitted an SPDX documentNamespace — the host check above is vacuous"
    );
}

// ── E-1-03 disclaimers in text mode must stay (regression) ──────────────────

#[test]
fn text_outputs_keep_the_disclaimer_line() {
    for (name, flags) in VARIANTS {
        let mut args = vec!["audit"];
        args.extend_from_slice(flags);
        args.push(VALID);
        let out = tallow(&args);
        assert!(
            String::from_utf8_lossy(&out.stdout).contains(DISCLAIMER),
            "{name}: text output lost the E-1-03 disclaimer line"
        );
    }
    // `pia` text keeps its E-1-03 disclaimer (JSON untouched, outside the freeze).
    let out = tallow(&["pia", VALID]);
    assert!(String::from_utf8_lossy(&out.stdout).contains(DISCLAIMER));
}
